E.forEach(e=>{const key=e.from<e.to?e.from+'|'+e.to:e.to+'|'+e.from;const r=sc.routes[key]=sc.routes[key]||{key:key,lanes:{}};const lk=e.from+'>'+e.to+'>'+e.kind;(r.lanes[lk]=r.lanes[lk]||{from:e.from,to:e.to,kind:e.kind,dash:e.dash,calls:[]}).calls.push(e);});
