const ribbon=new THREE.Mesh(new THREE.CylinderGeometry(tr,tr,1,12,1,true),rmat);ribbon.renderOrder=3;ribbon.userData.route=ln.key;world.add(ribbon);S.pick.push(ribbon);
const pmat=new THREE.PointsMaterial({color:0xffffff,size:6,sizeAttenuation:false,map:DOT,transparent:true,alphaTest:0.3,depthWrite:false});const pgeo=new THREE.BufferGeometry();pgeo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(NP*3),3));const pts=new THREE.Points(pgeo,pmat);pts.renderOrder=4;pts.frustumCulled=false;world.add(pts);
const amat=new THREE.MeshBasicMaterial({color:col,transparent:true,opacity:0.95});const arrow=new THREE.Mesh(new THREE.ConeGeometry(0.3,0.75,16),amat);arrow.renderOrder=4;world.add(arrow);
// the ports a lane carries, as a tag at its middle
